CREATE TABLE IF NOT EXISTS rental_delivery_intents (id CHAR(32) PRIMARY KEY, request_key VARCHAR(180) NOT NULL UNIQUE, provider VARCHAR(30) NOT NULL, operation VARCHAR(80) NOT NULL, entity_type VARCHAR(30) NOT NULL, entity_id BIGINT NOT NULL, entity_version INT NOT NULL, baseline_hash CHAR(64) NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, payload_json JSON NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'prepared', receipt_json JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
